create table unidades
(
    id             int auto_increment
        primary key,
    civilizacion   varchar(45)               not null,
    civilizacion_2 varchar(45)               not null,
    nombre         varchar(45)               not null,
    salud          int         default 0     not null,
    ataque         int         default 0     not null,
    alcance        int         default 0     not null,
    defensa        int         default 0     not null,
    velocidad      int         default 0     not null,
    vision         int         default 0     not null,
    coste          int         default 0     not null,
    moneda         varchar(20) default 'Oro' not null,
    alias          varchar(45)               not null,
    imagen         varchar(60)               not null,
    tipo           varchar(45)               not null
)
    charset = utf8mb4;

